/* ---- list [[цел]] ---- */
/* h.rc - число мест (переменных, полей, элементов), где хранится список.
   Список - значение: если мест несколько, перед изменением делается копия.
   Список сам учитывает свои элементы: при добавлении элемент получает ещё
   одно место хранения, при удалении - теряет его. */
struct dl_LLi { dan_hdr h; int64_t len, cap; dl_Li* *items; };

static void dl_LLi_destroy(dan_hdr *h) {
    dl_LLi *l = (dl_LLi *)(void *)h;
    for (int64_t i = 0; i < l->len; i++) dl_Li_release(l->items[i]);
    dan_free(l->items);
    dan_free(l);
}

static dl_LLi *dl_LLi_from(int64_t n, dl_Li* const *src) {
    dl_LLi *l = dan_alloc(sizeof *l);
    dan_hdr_new(&l->h, dl_LLi_destroy);
    l->len = n;
    l->cap = n < 4 ? 4 : n;
    l->items = dan_alloc((size_t)l->cap * sizeof(dl_Li*));
    for (int64_t i = 0; i < n; i++) l->items[i] = dl_Li_share(src[i]);
    return l;
}

static void dl_LLi_push(dl_LLi *l, dl_Li* v) {
    if (l->len == l->cap) {
        l->cap *= 2;
        l->items = dan_realloc(l->items, (size_t)l->cap * sizeof(dl_Li*));
    }
    l->items[l->len++] = dl_Li_share(v);
}

