/* копия для изменения: записи переносятся вместе с готовыми отпечатками (без повторного
   вычисления), место - с запасом вдвое, чтобы следующая запись не перестраивала таблицу */
static dm_Dii *dm_Dii_copy(const dm_Dii *d) {
    dm_Dii *r = dm_Dii_new();
    if (d->len == 0) return r;
    int64_t cap = d->len * 2 < 8 ? 8 : d->len * 2, m = 0;
    dm_Dii_block(r, cap);
    for (int64_t e = 0; e < d->n; e++) {
        if (!d->alive[e]) continue;
        r->keys[m] = DAN_ID(d->keys[e]); r->vals[m] = DAN_ID(d->vals[e]); r->hashes[m] = d->hashes[e]; r->alive[m] = true; m++;
    }
    r->n = r->len = m;
    dm_Dii_reindex(r);
    return r;
}
static dm_Dii *dm_Dii_mut(dm_Dii **pp) {
    dm_Dii *d = *pp;
    if (d->h.rc > 1) { dm_Dii *r = dm_Dii_copy(d); r->h.rc = 1; d->h.rc--; *pp = r; return r; }
    return d;
}
static dan_str dm_Dii_str(const dm_Dii *d) {
    dan_buf b = { NULL, 0, 0 };
    dan_buf_add(&b, "{");
    bool first = true;
    for (int64_t e = 0; e < d->n; e++) {
        if (!d->alive[e]) continue;
        if (!first) dan_buf_add(&b, ", ");
        first = false;
        dan_buf_add(&b, dan_int_to_str(d->keys[e]));
        dan_buf_add(&b, ": ");
        dan_buf_add(&b, dan_int_to_str(d->vals[e]));
    }
    dan_buf_add(&b, "}");
    return dan_buf_str(&b);
}
static void dm_Dii_write(const dm_Dii *d) { fputs(dm_Dii_str(d), stdout); }


static bool dm_Dii_eq(const dm_Dii *x, const dm_Dii *y) {
    if (x->len != y->len) return false;
    for (int64_t e = 0; e < x->n; e++) {
        if (!x->alive[e]) continue;
        int64_t f = dm_Dii_lookup(y, x->keys[e], x->hashes[e]);
        if (f < 0) return false;
        int64_t a = x->vals[e]; int64_t b = y->vals[f];
        if (!((a == b))) return false;
    }
    return true;
}


